import re

def parse(lines):
    rows = []
    idx = []
    stack = []
    for i, raw in enumerate(lines):
        s = raw.strip()
        if not s:
            continue
        opens = []
        cut = None
        q = None
        esc = False
        for j, c in enumerate(s):
            if q:
                if esc:
                    esc = False
                elif c == chr(92):
                    esc = True
                elif c == q:
                    q = None
                continue
            if c == "'" or c == '"':
                q = c
            elif c in '([{':
                opens.append(j)
            elif c in ')]}':
                if opens:
                    opens.pop()
                elif cut is None:
                    cut = j
        closers = 0
        if cut is not None:
            closers = sum(1 for c in s[cut:] if c in ')]}')
        text = s if cut is None else s[:cut]
        text = text.rstrip().rstrip(',').rstrip()
        m = re.match(r'^(?:(\w+)=)?(.*)$', text)
        field = m.group(1) or ''
        rest = m.group(2)
        nm = re.match(r'^(\w+)\(', rest)
        node = nm.group(1) if nm else ''
        value = rest
        if rest in ('[', '(') or (node and rest == node + '('):
            value = ''
        rows.append({'depth': len(stack), 'path': '/'.join(stack), 'field': field, 'node': node, 'value': value})
        idx.append(i)
        for k in opens:
            if s[k] == '[':
                stack.append((field or '') + '[]')
            else:
                stack.append(node or field or '()')
        for _ in range(min(closers, len(stack))):
            stack.pop()
    blocks = []
    if rows:
        blocks.append({'name': 'nodes', 'kind': 'table', 'lines': idx, 'records': rows})
    return {'blocks': blocks, 'skip': []}
